439	// padded returns body followed by spaces up to exactly size bytes (valid JSON).
440	func padded(t *testing.T, body string, size int) string {
441		t.Helper()
442		if len(body) > size {
443			t.Fatalf("body (%d bytes) is longer than %d", len(body), size)
444		}
445		return body + strings.Repeat(" ", size-len(body))
446	}
