448	// writeBounded writes at most limit bytes of s and stops: no test server ever
449	// serves more than the few MiB a test asks for.
450	func writeBounded(w http.ResponseWriter, s string, limit int) {
451		if len(s) > limit {
452			s = s[:limit]
453		}
454		_, _ = io.WriteString(w, s)
455	}
